const appModeCss = `
/* Native simulator app mode: fill the WebView, remove exported browser phone shell. */
html,body{width:100%;height:100%;min-height:100%;overflow:hidden;padding:0;background:#f7f5ef}
body{display:block;align-items:initial;justify-content:initial}
.phone{width:100vw;height:100vh;max-height:none;border-radius:0;box-shadow:none;background:#f7f5ef}
.phone:after{border-radius:0;box-shadow:inset 0 0 0 1px rgba(112,126,120,.12),inset 0 -72px 110px rgba(112,126,120,.08)}
.topbar{top:calc(env(safe-area-inset-top,0px) + 54px)}
.metric-row{padding-top:calc(env(safe-area-inset-top,0px) + 84px)}
.gauge{top:calc(env(safe-area-inset-top,0px) + 188px)}
.hero-center{top:calc(env(safe-area-inset-top,0px) + 294px)}
.hero{height:calc(686px + env(safe-area-inset-top,0px))}
@supports (height:100dvh){.phone{height:100dvh}}
`;

const visualRefreshCss = `
/* Visual refresh: calmer premium health dashboard for the native simulator. */
:root{
  --ink:#fbf7ee;--muted:rgba(251,247,238,.74);--dim:rgba(251,247,238,.52);
  --card:rgba(8,15,16,.70);--glass:rgba(31,44,45,.58);--line:rgba(255,255,255,.11);
  --teal:#8ee7d6;--blue:#c5e0f0;--gold:#e4bd55;--rose:#dfa0b0;--amber:#ead37a;
}
html,body{background:#071011}
.topbar{top:calc(env(safe-area-inset-top,0px) + 50px);padding:0 26px}
.wordmark{font-size:21px;letter-spacing:1px;text-shadow:0 10px 24px rgba(0,0,0,.30)}
.icon-btn{width:38px;height:38px;color:rgba(251,247,238,.88)}
.today{background:#060b0c}
.hero{height:calc(652px + env(safe-area-inset-top,0px));background:#071011}
.hero-bg{filter:saturate(.96) contrast(1.03) brightness(.88);transform:scale(1.025)}
.hero:after{background:radial-gradient(ellipse at 50% 34%,rgba(235,245,235,.16),transparent 31%),linear-gradient(180deg,rgba(6,24,27,.20) 0%,rgba(5,12,14,.02) 32%,rgba(4,8,9,.46) 72%,#060b0c 100%)}
.grain{opacity:.075}
.metric-row{gap:16px;padding:calc(env(safe-area-inset-top,0px) + 82px) 22px 4px 22px}
.metric{min-width:72px;color:rgba(251,247,238,.68)}
.metric.active{transform:scale(1.035)}
.metric-bubble{width:62px;height:62px;margin-bottom:8px;background:rgba(232,240,232,.13);box-shadow:inset 0 0 0 1px rgba(255,255,255,.10),0 14px 30px rgba(0,0,0,.18);backdrop-filter:blur(18px)}
.metric.active .metric-bubble{background:rgba(232,240,232,.22);box-shadow:inset 0 0 0 1px rgba(255,255,255,.16),0 18px 34px rgba(0,0,0,.22)}
.metric-val{font-size:23px;font-weight:450;letter-spacing:0}
.metric-label{font-size:13px;font-weight:760;color:rgba(251,247,238,.66)}
.metric.active .metric-label{color:rgba(251,247,238,.92)}
.gauge{left:25px;right:25px;top:calc(env(safe-area-inset-top,0px) + 184px);height:172px}
.arc-main{stroke:rgba(251,247,238,.90);stroke-width:7.2;filter:drop-shadow(0 0 8px rgba(244,238,218,.16))}
.arc-shadow{stroke:rgba(255,255,255,.16);stroke-width:7.6}
.arc-tail{stroke:rgba(251,247,238,.42);stroke-width:2}
.arc-dot{fill:rgba(251,247,238,.68)}
.arc-label{font-size:16px;color:rgba(251,247,238,.62)}
.hero-center{top:calc(env(safe-area-inset-top,0px) + 286px);left:28px;right:28px;text-shadow:0 14px 34px rgba(0,0,0,.28)}
.hero-icons{height:32px;gap:10px;margin-bottom:2px}
.hero-icon{width:28px;height:28px;background:rgba(8,18,20,.44);box-shadow:inset 0 0 0 1px rgba(255,255,255,.06)}
.hero-icon.gold{color:var(--gold);background:rgba(86,113,112,.54)}
.hero-score{font-size:74px;line-height:.88;font-weight:330;letter-spacing:0}
.hero-label{margin-top:14px;font-size:14px;font-weight:850;letter-spacing:.08em}
.hero-title{max-width:316px;margin-top:20px;font-size:36px;line-height:1.18;letter-spacing:0}
.hero-copy{max-width:314px;margin-top:15px;font-size:14.5px;line-height:1.68;color:rgba(251,247,238,.74)}
.learn{height:46px;min-width:128px;padding:0 22px;background:rgba(245,243,232,.18);box-shadow:inset 0 0 0 1px rgba(255,255,255,.12),0 14px 30px rgba(0,0,0,.18);font-size:15px}
.hero-center .learn{margin-top:22px}
.today[data-stage="mid"] .hero-bg{filter:saturate(.88) contrast(1) brightness(.74)}
.today[data-stage="full"] .hero-bg{filter:saturate(.78) contrast(.96) brightness(.54)}
.feed{margin-top:-8px;padding:0 20px 124px}
.drawer-card{min-height:286px;border-radius:18px;background:linear-gradient(180deg,rgba(13,21,22,.74),rgba(7,12,13,.72));box-shadow:inset 0 0 0 1px rgba(255,255,255,.075),0 22px 42px rgba(0,0,0,.26);padding:23px 24px 22px;margin-bottom:14px}
.drawer-card:before{background:radial-gradient(circle at 48% -6%,var(--cardGlow,rgba(120,210,190,.20)),transparent 38%),linear-gradient(180deg,rgba(255,255,255,.03),rgba(0,0,0,.08))}
.round-icon{width:36px;height:36px;background:rgba(255,255,255,.12)}
.card-name{font-size:20px}
.status{font-size:12px}
.card-score{margin-top:28px;font-size:66px;letter-spacing:0}
.card-serif{margin-top:13px;font-size:31px;line-height:1.17;letter-spacing:0}
.card-copy{margin-top:18px;font-size:15px;line-height:1.68;color:rgba(251,247,238,.72)}
.stats{gap:16px;font-size:15px}
.bottom{left:18px;right:18px;bottom:calc(env(safe-area-inset-bottom,0px) + 18px);gap:10px}
.tabs{height:58px;background:rgba(20,31,32,.66);box-shadow:inset 0 0 0 1px rgba(255,255,255,.09),0 16px 34px rgba(0,0,0,.24);padding:5px}
.tab{height:48px;font-size:11px;color:rgba(251,247,238,.52)}
.tab.active{background:rgba(255,255,255,.10);color:rgba(251,247,238,.96)}
.tab.active:first-child{background:rgba(255,255,255,.10)}
.tab svg{width:23px;height:23px}
.plus{width:58px;height:58px;background:rgba(22,32,33,.74);box-shadow:inset 0 0 0 1px rgba(255,255,255,.10),0 16px 34px rgba(0,0,0,.24)}
.cloud-mascot{right:0;top:54dvh;bottom:auto;width:146px;height:146px;filter:drop-shadow(0 18px 30px rgba(0,0,0,.26));opacity:.97}
.cloud-mascot:before{right:32px;bottom:22px;width:56px;height:12px;opacity:.56}
.detail-score,.wall-num{letter-spacing:0}
@media(max-height:760px){
  .hero{height:calc(618px + env(safe-area-inset-top,0px))}
  .hero-center{top:calc(env(safe-area-inset-top,0px) + 270px)}
  .hero-title{font-size:36px}
  .cloud-mascot{right:0;top:52dvh;bottom:auto;width:132px;height:132px}
}
`;

