const ecosystemCss = `
/* VIVI ecosystem backgrounds: country x energy scenes with low-motion ambience. */
.hero{
  --eco-accent:rgba(95,174,159,.56);
  --eco-accent-soft:rgba(214,232,224,.44);
  --eco-haze:rgba(226,234,228,.54);
  --eco-overlay:rgba(72,92,86,.16);
  --eco-sat:.82;
  --eco-bright:.96;
  --eco-open-sat:.70;
  --eco-open-bright:.80;
  --eco-duration:24s;
  --eco-pan-x-start:-1%;
  --eco-pan-x-end:1%;
  --eco-pan-y-start:.2%;
  --eco-pan-y-end:-.8%;
  --eco-light-x:52%;
  --eco-light-y:26%;
}
.hero-bg{
  overflow:hidden;
  background-image:var(--eco-bg,var(--hero-bg));
  background-position:var(--eco-pos,var(--hero-pos,center));
  background-size:cover;
  filter:saturate(var(--eco-sat)) contrast(.94) brightness(var(--eco-bright));
  transform:scale(1.045) translate3d(var(--eco-pan-x-start),var(--eco-pan-y-start),0);
  transform-origin:center;
  animation:ecoDrift var(--eco-duration) ease-in-out infinite alternate;
  will-change:transform,filter;
}
.hero-bg:before{
  content:"";
  position:absolute;
  inset:-16%;
  pointer-events:none;
  background:
    radial-gradient(circle at 26% 22%,var(--eco-haze),transparent 28%),
    radial-gradient(circle at 76% 36%,rgba(255,255,255,.28),transparent 30%),
    linear-gradient(112deg,transparent 4%,var(--eco-haze) 38%,transparent 72%);
  opacity:.48;
  filter:blur(22px);
  mix-blend-mode:screen;
  animation:ecoMist 38s ease-in-out infinite alternate;
}
.hero-bg:after{
  content:"";
  position:absolute;
  inset:0;
  pointer-events:none;
  background:
    radial-gradient(circle at var(--eco-light-x) var(--eco-light-y),var(--eco-accent-soft),transparent 34%),
    linear-gradient(180deg,rgba(255,255,255,.18),var(--eco-overlay) 72%,rgba(247,245,239,.18));
  opacity:.52;
  mix-blend-mode:soft-light;
}
.today .hero:after{
  background:
    radial-gradient(ellipse at 50% 34%,rgba(255,255,255,.26),transparent 32%),
    linear-gradient(180deg,rgba(250,248,241,.18) 0%,rgba(250,248,241,.04) 36%,rgba(247,245,239,.34) 78%,rgba(247,245,239,.68) 100%);
}
.hero[data-energy="low"] .hero-bg{filter:saturate(var(--eco-sat)) contrast(.90) brightness(var(--eco-bright))}
.hero[data-energy="mid"] .hero-bg{filter:saturate(var(--eco-sat)) contrast(.94) brightness(var(--eco-bright))}
.hero[data-energy="high"] .hero-bg{filter:saturate(var(--eco-sat)) contrast(.98) brightness(var(--eco-bright))}
.today[data-drawer-state="half"] .hero-bg,
.today[data-drawer-state="expanded"] .hero-bg{
  filter:saturate(var(--eco-open-sat)) contrast(.90) brightness(var(--eco-open-bright)) blur(1px);
}
.today[data-drawer-state="half"] .hero:after,
.today[data-drawer-state="expanded"] .hero:after{
  background:
    radial-gradient(ellipse at 48% 36%,rgba(255,255,255,.24),transparent 32%),
    linear-gradient(180deg,rgba(250,248,241,.16) 0%,var(--eco-overlay) 54%,rgba(36,48,47,.24) 100%);
}
.home-drawer{--cardGlow:var(--eco-accent-soft)}
.drawer-summary-state,.drawer-question button,.preview-btn,.send,.mic-btn{color:#3f8379}
@keyframes ecoDrift{
  0%{transform:scale(1.045) translate3d(var(--eco-pan-x-start),var(--eco-pan-y-start),0)}
  100%{transform:scale(1.105) translate3d(var(--eco-pan-x-end),var(--eco-pan-y-end),0)}
}
@keyframes ecoMist{
  0%{transform:translate3d(-2.2%,.8%,0) scale(1)}
  100%{transform:translate3d(2.6%,-.7%,0) scale(1.04)}
}
@media(prefers-reduced-motion:reduce){
  .hero-bg,.hero-bg:before{animation:none!important}
  .hero-bg{transform:scale(1.035) translate3d(0,0,0)!important}
}
`;


