  function bindHealthGalaxySwipe(){var hero=document.querySelector('.health-galaxy-hero');if(!hero||hero.dataset.swipeBound==='1')return;hero.dataset.swipeBound='1';hero.addEventListener('pointerdown',function(e){if(e.button&&e.button!==0)return;healthSwipeStart={x:e.clientX,y:e.clientY,t:Date.now(),moved:false}}, {passive:true});hero.addEventListener('pointermove',function(e){if(!healthSwipeStart)return;var dx=e.clientX-healthSwipeStart.x,dy=e.clientY-healthSwipeStart.y;if(Math.abs(dx)>12&&Math.abs(dx)>Math.abs(dy)*1.15)healthSwipeStart.moved=true}, {passive:true});hero.addEventListener('pointerup',function(e){if(!healthSwipeStart)return;var dx=e.clientX-healthSwipeStart.x,dy=e.clientY-healthSwipeStart.y,dt=Date.now()-healthSwipeStart.t;healthSwipeStart=null;if(Math.abs(dx)<38||Math.abs(dx)<Math.abs(dy)*1.15||dt>900)return;focusAdjacentHealthNode(dx<0?1:-1)});hero.addEventListener('pointercancel',function(){healthSwipeStart=null})}
  function renderHealthVoicePicker(){var list=document.getElementById('healthVoiceModels'),current=document.getElementById('healthVoiceCurrent');if(!list)return;var active=currentVoiceModel();if(current)current.textContent='当前：'+(active&&active.name?active.name:'未选择');list.innerHTML=voiceModelOptions.map(function(v){var activeClass=voiceSettings.voiceId===v.id?' active':'';var disabledClass=v.available?'':' disabled';var warn=v.notRecommended?'<span class="model-warning">对照</span>':'';var source=v.provider?'<div class="model-source">'+v.provider+'</div>':'';var buttons=v.available?'<div class="model-actions"><button data-health-voice-preview="'+v.id+'">试听</button><button class="select" data-health-voice-select="'+v.id+'">'+(voiceSettings.voiceId===v.id?'已选择':'选择')+'</button></div>':'<div class="model-pending">待生成真实 MP3</div>';return '<article class="health-voice-model'+activeClass+disabledClass+'"><div class="model-top"><span class="model-tag">'+(v.tag||'可选')+'</span>'+warn+'</div><div class="model-name">'+v.name+'</div>'+source+'<p class="model-desc">'+v.desc+'</p>'+buttons+'</article>'}).join('')}
  function renderVoiceSettings(){var grid=document.getElementById('voicePresetGrid');if(grid){grid.innerHTML=voicePresets.map(function(v){return '<div class="preset-card '+(voiceSettings.voiceId===v.id?'active':'')+'" data-voice-preset="'+v.id+'"><div class="preset-name">'+v.name+'</div><div class="preset-desc">'+v.desc+'</div><div class="preview-row"><button class="preview-btn" data-voice-preview="'+v.id+'">试听</button></div></div>'}).join('')}var speed=document.querySelector('[data-voice-range="speed"]'),pitch=document.querySelector('[data-voice-range="pitch"]'),nick=document.querySelector('[data-voice-nickname]');if(speed)speed.value=voiceSettings.speed;if(pitch)pitch.value=voiceSettings.pitch;if(nick)nick.value=voiceSettings.nickname;var sv=document.getElementById('speedValue'),pv=document.getElementById('pitchValue');if(sv)sv.textContent=Number(voiceSettings.speed).toFixed(2);if(pv)pv.textContent=Number(voiceSettings.pitch).toFixed(2);renderHealthVoicePicker()}
  function voiceSheet(open){var sheet=document.getElementById('voiceSheet');if(!sheet)return;renderVoiceSettings();sheet.classList.toggle('open',!!open)}
  function playVoiceTone(ms){try{voiceAudioCtx=voiceAudioCtx||new (window.AudioContext||window.webkitAudioContext)();var ctx=voiceAudioCtx,now=ctx.currentTime;var gain=ctx.createGain();gain.gain.setValueAtTime(.0001,now);gain.gain.exponentialRampToValueAtTime(.045,now+.05);gain.gain.exponentialRampToValueAtTime(.0001,now+(ms/1000));gain.connect(ctx.destination);[0,1,2].forEach(function(i){var osc=ctx.createOscillator();osc.type=i===1?'triangle':'sine';osc.frequency.setValueAtTime(360+i*95,now);osc.frequency.linearRampToValueAtTime(420+i*75,now+(ms/1000));osc.connect(gain);osc.start(now+i*.025);osc.stop(now+(ms/1000))})}catch(_){}}
  function selectedAudioPath(){var file=voiceSettings.audioFile||voiceSettings.sampleFile||'';if(!file)return '';if(/^https?:|^file:|^data:/i.test(file))return file;if(file.indexOf('./')===0)return file;if(file.indexOf('voice-bakeoff/')===0)return './'+file;if(file.indexOf('audio/')===0)return './voice-bakeoff/'+file;return './voice-bakeoff/audio/'+file}
  function playSelectedAudio(onDone){var src=selectedAudioPath();if(!src)return false;try{currentVoiceAudio=new Audio(src);currentVoiceAudio.preload='auto';currentVoiceAudio.onended=function(){currentVoiceAudio=null;if(onDone)onDone()};currentVoiceAudio.onerror=function(){currentVoiceAudio=null;if(onDone)onDone()};var p=currentVoiceAudio.play();if(p&&p.catch)p.catch(function(){currentVoiceAudio=null;if(onDone)onDone()});return true}catch(_){currentVoiceAudio=null;return false}}
