  function voiceTextFor(scope,presetId){if(presetId){var p=voicePresets.find(function(v){return v.id===presetId})||voicePresets[0];return (voiceSettings.nickname||'主人')+'，我是'+p.name+'。以后我会用这个声音，把身体状态讲给你听。'}if(scope==='advisor'){return document.getElementById('advisorReplyText')?.textContent||'今天状态不错，可以安排重要任务，但训练仍建议保留热身和收操。'}return document.getElementById('healthVoiceText')?.textContent||'主人，今天身体状态还不错，重要事情可以推进，但也要记得留一点缓冲。'}
  function stopSpeech(){clearTimeout(voiceTimer);try{if(currentVoiceAudio){currentVoiceAudio.pause();currentVoiceAudio.currentTime=0}}catch(_){}currentVoiceAudio=null;try{if('speechSynthesis' in window)window.speechSynthesis.cancel()}catch(_){}currentUtterance=null;document.querySelectorAll('.playing').forEach(function(n){n.classList.remove('playing')})}
