  function mockMicInput(){var mic=document.querySelector('[data-mic-input]'),out=document.getElementById('advisorRecognized'),input=document.getElementById('advisorInput'),reply=document.getElementById('advisorReplyText');if(mic)mic.classList.add('listening');if(out)out.textContent='正在听...';setCloudReaction('listen',{force:true});setTimeout(function(){if(mic)mic.classList.remove('listening');var text='我今天有点累，还适合运动吗？';if(input)input.value=text;if(out)out.textContent='识别结果：'+text;if(reply)reply.textContent=voiceSettings.nickname+'，今天可以动，但建议换轻一点。准备度还不错，不过恢复速度略慢，快走 20 分钟或拉伸会更适合。';setCloudReaction('think',{force:true,returnIdle:true,hold:1100})},1150)}
