  document.addEventListener('input',function(e){var range=e.target.closest('[data-voice-range]');if(range){voiceSettings[range.getAttribute('data-voice-range')]=Number(range.value);persistVoice();renderVoiceSettings()}var nick=e.target.closest('[data-voice-nickname]');if(nick){voiceSettings.nickname=nick.value||'主人';persistVoice()}});
