  function renderHomeDrawer(){var meta=currentHomeDrawerMeta();if(drawerSummaryTitle)drawerSummaryTitle.textContent=meta.summary;if(drawerSummaryState)drawerSummaryState.textContent=meta.state;if(drawerInsight)drawerInsight.textContent=meta.insight;if(drawerChips)drawerChips.innerHTML=meta.chips.map(function(x){return '<span class="drawer-chip">'+x+'</span>'}).join('');if(drawerAnswer&&drawerAnswer.classList.contains('show'))drawerAnswer.textContent='VIVI：'+meta.answer}
  function closeDrawerAssistant(clearAnswer){if(homeDrawer)homeDrawer.classList.remove('assistant-open');if(app)app.classList.remove('drawer-assistant-open');if(drawerQuestionInput)drawerQuestionInput.value='';if(clearAnswer!==false&&drawerAnswer){drawerAnswer.classList.remove('show');drawerAnswer.textContent=''}}
  function resetHomeScroll(){if(homeDrawer){homeDrawer.scrollTop=0;homeDrawer.scrollLeft=0}if(today){today.scrollTop=0;today.scrollLeft=0}if(app){app.scrollTop=0;app.scrollLeft=0}var screens=document.querySelector('.screens');if(screens){screens.scrollTop=0;screens.scrollLeft=0}try{window.scrollTo(0,0)}catch(_){}syncVisualViewportOffset()}
  function setDrawer(state){state=state||'collapsed';if(['collapsed','half','expanded'].indexOf(state)<0)state='collapsed';S.drawer=state;if(homeDrawer)homeDrawer.setAttribute('data-drawer-state',state);if(today){today.setAttribute('data-drawer-state',state);today.scrollTop=0}if(app){app.setAttribute('data-drawer-state',state);app.classList.toggle('drawer-open',state!=='collapsed')}resetHomeScroll();if(state==='collapsed')closeDrawerAssistant(false)}
