  function sendDrawerQuestion(){var meta=currentHomeDrawerMeta(),q=drawerQuestionInput&&drawerQuestionInput.value?drawerQuestionInput.value.trim():'';if(!q)return;if(drawerAnswer){drawerAnswer.textContent='VIVI：'+meta.answer;drawerAnswer.classList.add('show')}if(drawerQuestionInput)drawerQuestionInput.value='';resetHomeScroll();setTimeout(syncVisualViewportOffset,80);setCloudReaction('speak',{force:true,returnIdle:true,hold:1500})}
  var originalSetHero=setHero;
  setHero=function(key){originalSetHero(key);renderHomeDrawer()};
  renderHomeDrawer();
