  function updateTodayScrollState(){
    var root=document.getElementById('todayScreen')||today;
    if(!root)return;
    var y=root.scrollTop||0;
    var h=window.innerHeight||root.clientHeight||840;
    var state=y<h*.28?'top':(y<h*.82?'mid':'full');
    root.setAttribute('data-today-scroll',state);
    root.style.setProperty('--today-scroll-progress',String(Math.max(0,Math.min(1,y/Math.max(1,h)))));
  }
  function bindTodayScrollFlow(){
    var root=document.getElementById('todayScreen')||today;
    if(!root||root.dataset.todayFlowBound==='1')return;
    root.dataset.todayFlowBound='1';
    root.setAttribute('data-today-flow','scroll');
    root.setAttribute('data-today-scroll','top');
    root.addEventListener('scroll',updateTodayScrollState,{passive:true});
    updateTodayScrollState();
  }
  function handleTideDrawerByPoint(e){return false}
