    if(typeof renderTideThemePanel==='function')renderTideThemePanel();
    panel=document.getElementById('tideThemePanel')||panel;
    if(panel){
      panel.classList.add('open','profile-mode');
      panel.setAttribute('aria-hidden','false');
    }
