function applyTodayEnergyReportIa(html) {
  if (!html.includes("VIVI Today Energy Report IA 20260622")) {
    if (html.includes("</head>")) {
      html = html.replace("</head>", `<style>\n${todayEnergyReportIaCss}\n</style>\n</head>`);
    } else {
      html = html.replace("</style>", `${todayEnergyReportIaCss}\n</style>`);
    }
  }

  if (!html.includes("openTodayEnergyReportV1")) {
    html = html.replace(
      "  today.addEventListener('scroll',function(){",
      `${todayEnergyReportIaScript}\n  today.addEventListener('scroll',function(){`
    );
  }

  return html;
}

