const threeTabIaFixScript = String.raw`
  var threeTabHealthSummaryV2=[
    {key:'weekly',cls:'readiness',label:'平均准备度',value:'88',sub:'较上周 +6',accent:'#8370d7',soft:'rgba(131,112,215,.22)'},
    {key:'sleepdebt',cls:'sleepdebt',label:'睡眠负债',value:'+2',sub:'较上周 -1.2h',accent:'#dc6f72',soft:'rgba(220,111,114,.20)'},
    {key:'cycle',cls:'cycle',label:'周期稳定度',value:'78%',sub:'稳定 · 黄体期',accent:'#8f72d8',soft:'rgba(143,114,216,.18)'},
    {key:'stress',cls:'stress',label:'压力恢复',value:'中等',sub:'恢复中 · 需短休',accent:'#d99b42',soft:'rgba(217,155,66,.18)'}
  ];
  function threeTabEscV2(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
  function threeTabDetailKeyV2(key){return ({weekly:'weekly',readiness:'weekly',sleepdebt:'sleep',sleep:'sleep',cycle:'cycle',stress:'stress',recovery:'recovery',activity:'activity',heartrate:'recovery',hrv:'recovery',daily:'weekly',report:'weekly'})[key]||'weekly'}
  function threeTabSummaryOpenKeyV10(key){return ({weekly:'readiness',readiness:'readiness',sleepdebt:'sleep',sleep:'sleep',cycle:'cycle',stress:'stress',pressure:'stress',recovery:'readiness',activity:'activity',heartrate:'heartrate',hrv:'heartrate'})[key]||'readiness'}
  function renderTodayActionFeedV2(){
    return '<section class="today-start-charge-wrap"><button class="today-start-charge-card" type="button" data-report-charge><span>今日推荐行动</span><strong>开始充电</strong><em>3 分钟延长呼气 · 睡眠修复白噪音</em><i>根据今日能量和周期状态，直接进入最适合的恢复节奏。</i><b>→</b></button></section>';
  }
  function ensureTodayCycleEntryV2(){
    var phase=document.querySelector('#todayEnergyPageV1 .today-phase');
    if(!phase||phase.dataset.cycleEntryV2==='1')return;
    phase.dataset.cycleEntryV2='1';
    phase.innerHTML='<button class="today-cycle-entry" type="button" data-today-cycle-settings><strong>黄体期</strong><span>周期第22天 · 今日能量趋势平稳</span></button>';
  }
  function ensureTodayThreeTabV2(){
    var page=document.getElementById('todayEnergyPageV1');
    if(!page)return;
    ensureTodayCycleEntryV2();
    var gauge=page.querySelector('.energy-gauge');
    if(gauge){
      gauge.dataset.todayReportReady='1';
      if(!gauge.querySelector('[data-today-energy-report]')){
        gauge.insertAdjacentHTML('beforeend','<button class="energy-report-entry" type="button" data-today-energy-report>查看今日身体报告</button>');
      }
    }
    var feed=page.querySelector('.today-energy-feed');
    if(feed&&feed.dataset.threeTabV2!=='1'){
      feed.dataset.threeTabV2='1';
      feed.innerHTML=renderTodayActionFeedV2();
    }
  }
  function todayCycleSettingsDataV2(){
    var base={lastPeriod:'2026-05-30',cycleLength:'28',periodLength:'5',phase:'黄体期',source:'手动记录 + 设备同步'};
    try{var saved=localStorage.getItem('vivi:cycleSettingsV2');if(saved)base=Object.assign(base,JSON.parse(saved))}catch(_){}
    return base;
  }
  function renderTodayCycleSettingsV2(){
    var d=todayCycleSettingsDataV2();
    return '<div class="today-cycle-settings-sheet" role="dialog" aria-modal="true" aria-label="周期设置"><div class="today-cycle-settings-handle"></div><header class="today-cycle-settings-head"><div><h2>周期设置</h2><p>用于校准 Today 的周期阶段、能量解释和饮食建议。</p></div><button class="today-cycle-settings-close" type="button" data-cycle-settings-close aria-label="关闭">×</button></header><div class="today-cycle-settings-form"><label class="today-cycle-settings-row"><span>末次经期</span><input type="date" data-cycle-field="lastPeriod" value="'+threeTabEscV2(d.lastPeriod)+'"></label><label class="today-cycle-settings-row"><span>周期长度</span><input type="number" min="20" max="45" data-cycle-field="cycleLength" value="'+threeTabEscV2(d.cycleLength)+'"></label><label class="today-cycle-settings-row"><span>经期长度</span><input type="number" min="2" max="10" data-cycle-field="periodLength" value="'+threeTabEscV2(d.periodLength)+'"></label><label class="today-cycle-settings-row"><span>当前阶段校准</span><select data-cycle-field="phase"><option '+(d.phase==='黄体期'?'selected':'')+'>黄体期</option><option '+(d.phase==='卵泡期'?'selected':'')+'>卵泡期</option><option '+(d.phase==='排卵期'?'selected':'')+'>排卵期</option><option '+(d.phase==='经期'?'selected':'')+'>经期</option></select></label><label class="today-cycle-settings-row"><span>数据来源</span><select data-cycle-field="source"><option '+(d.source==='手动记录 + 设备同步'?'selected':'')+'>手动记录 + 设备同步</option><option '+(d.source==='仅手动记录'?'selected':'')+'>仅手动记录</option><option '+(d.source==='等待同步'?'selected':'')+'>等待同步</option></select></label><button class="today-cycle-settings-save" type="button" data-cycle-settings-save>保存设置</button></div></div>';
  }
  function ensureTodayCycleSettingsLayerV2(){
    var layer=document.getElementById('todayCycleSettingsLayerV2');
    if(layer)return layer;
    layer=document.createElement('section');
    layer.id='todayCycleSettingsLayerV2';
    layer.className='today-cycle-settings-layer';
    layer.setAttribute('aria-hidden','true');
    if(app)app.appendChild(layer);
    return layer;
  }
  function openTodayCycleSettingsV2(){
    var layer=ensureTodayCycleSettingsLayerV2();
    layer.innerHTML=renderTodayCycleSettingsV2();
    layer.classList.add('open');
    layer.setAttribute('aria-hidden','false');
  }
  function closeTodayCycleSettingsV2(){
    var layer=document.getElementById('todayCycleSettingsLayerV2');
    if(layer){layer.classList.remove('open');layer.setAttribute('aria-hidden','true')}
  }
  function saveTodayCycleSettingsV2(){
    var layer=document.getElementById('todayCycleSettingsLayerV2');
    if(!layer)return;
    var data={};
    layer.querySelectorAll('[data-cycle-field]').forEach(function(input){data[input.getAttribute('data-cycle-field')]=input.value});
    try{localStorage.setItem('vivi:cycleSettingsV2',JSON.stringify(data))}catch(_){}
    document.querySelectorAll('.today-cycle-entry strong').forEach(function(n){n.textContent=data.phase||'黄体期'});
    document.querySelectorAll('.today-cycle-entry span').forEach(function(n){n.textContent='周期第22天 · 今日能量趋势平稳'});
    closeTodayCycleSettingsV2();
    if(typeof showVitalsStarNoticeV6==='function')showVitalsStarNoticeV6('周期设置已保存');
  }
function renderHealthSummaryGridV2(){
    return threeTabHealthSummaryV2.map(function(x){
      var summaryKey=threeTabSummaryOpenKeyV10(x.key);
      return '<button class="tile health-summary-tile-v2 '+threeTabEscV2(x.cls)+'" type="button" data-health-summary-detail="'+threeTabEscV2(x.key)+'" data-health-summary-open="'+threeTabEscV2(summaryKey)+'" style="--accent:'+threeTabEscV2(x.accent)+';--accent-soft:'+threeTabEscV2(x.soft)+'"><div class="tile-k">'+threeTabEscV2(x.label)+'</div><div class="tile-v">'+threeTabEscV2(x.value)+'</div><div class="tile-s">'+threeTabEscV2(x.sub)+'</div></button>';
    }).join('');
  }
  function ensureHealthSummaryGridV2(){
    var pad=document.querySelector('.screen[data-screen="health"] .pad');
    var grid=pad&&pad.querySelector('.grid');
    if(!pad||!grid)return;
    if(!pad.querySelector('.health-summary-head-v2')){
      grid.insertAdjacentHTML('beforebegin','<section class="health-summary-head-v2"><div><h2>我的健康总结</h2><p>关键数据留在这里沉淀，点击进入睡眠、周期、压力详情。</p></div><button class="health-summary-head-action-v2" type="button" data-health-summary-open="readiness" data-open-health-module-v1 data-health-detail-key="weekly" data-health-detail-source="health" data-health-detail-daily="0" aria-label="查看健康详情">查看详情</button></section>');
    }
    if(grid.dataset.healthSummaryV2!=='1'){
      grid.dataset.healthSummaryV2='1';
      grid.innerHTML=renderHealthSummaryGridV2();
      grid.querySelectorAll('[data-health-summary-detail]').forEach(function(btn){
        var key=(btn.getAttribute('data-health-summary-detail')||'weekly');
        btn.removeAttribute('data-health-summary-detail');
        btn.setAttribute('data-open-health-module-v1','1');
        btn.setAttribute('data-health-detail-key',key);
        btn.setAttribute('data-health-summary-open',threeTabSummaryOpenKeyV10(key));
        btn.setAttribute('data-health-detail-source','health');
        btn.setAttribute('data-health-detail-daily','0');
      });
    }
    var head=pad.querySelector('.health-summary-head-v2');
    if(head&&!head.querySelector('.health-summary-head-action-v2')){
      head.insertAdjacentHTML('beforeend','<button class="health-summary-head-action-v2" type="button" data-health-summary-open="readiness" data-open-health-module-v1 data-health-detail-key="weekly" data-health-detail-source="health" data-health-detail-daily="0" aria-label="查看健康详情">查看详情</button>');
    }
  }
  function renderHealthDailyReportSourcesV2(){
    var sources=(todayEnergyReportDataV1&&todayEnergyReportDataV1.sources)||[];
    return sources.slice(0,4).map(function(s){
      return '<button class="health-daily-source-v2" type="button" data-open-health-module-v1 data-health-detail-key="'+threeTabEscV2(s.key||'weekly')+'" data-health-detail-source="health" data-health-detail-daily="0"><span>'+threeTabEscV2(s.name)+'</span><strong>'+threeTabEscV2(s.value)+'</strong><em>'+threeTabEscV2(s.tag)+' · 查看详情</em></button>';
    }).join('');
  }
  function renderHealthDailyReportV2(){
    var d=todayEnergyReportDataV1||{energyScore:'80',summary:'睡眠恢复较好，活动目标已经达成；压力恢复仍需要留意。'};
    return '<section class="health-daily-report-v2" data-health-daily-report-v2><header><div><div class="health-daily-report-k">今日身体报告</div><h2>今日能量 '+threeTabEscV2(d.energyScore)+'</h2><p>'+threeTabEscV2(d.summary)+'</p></div><div class="health-daily-score-v2"><strong>'+threeTabEscV2(d.energyScore)+'</strong></div></header><div class="health-daily-source-grid-v2">'+renderHealthDailyReportSourcesV2()+'</div></section>';
  }
  function injectHealthDailyReportV2(){
    var body=document.getElementById('healthDetailBody');
    if(!body)return;
    var old=body.querySelector('[data-health-daily-report-v2]');
    if(old)old.remove();
    var date=body.querySelector('.health-detail-date');
    if(date)date.insertAdjacentHTML('afterend',renderHealthDailyReportV2());
    else body.insertAdjacentHTML('afterbegin',renderHealthDailyReportV2());
  }
  function openHealthDetailFromThreeTabV2(key,withDaily){
    var detail=threeTabDetailKeyV2(key);
    if(typeof openHealthModuleEntryV1==='function')openHealthModuleEntryV1(detail,{source:withDaily?'today':'health',daily:!!withDaily});
    else if(typeof openButtonAuditHealthDetailV1==='function')openButtonAuditHealthDetailV1(detail,{origin:withDaily?'today':'health',daily:!!withDaily});
    else if(typeof openVitoraNativeHealthDetail==='function')openVitoraNativeHealthDetail(detail,{origin:withDaily?'today':'health',daily:!!withDaily});
  }
  function openTodayBodyReportV2(){openHealthOverviewFromReportV1()}
  function ensureChargeRecommendationV2(){
    var root=document.querySelector('[data-charge-mode-v7]');
    if(!root)return;
    root.setAttribute('data-charge-reco-v2','1');
    var title=root.querySelector('.vitals-star-title');
    if(title)title.textContent='探索';
    var copy=root.querySelector('.vitals-star-copy');
    if(copy&&!copy.querySelector('.charge-precision-title'))copy.insertAdjacentHTML('afterbegin','<div class="charge-precision-title">为今天的你，精准充电</div>');
    var tag=copy&&copy.querySelector('.vitals-star-tag');
    if(tag)tag.textContent='✨ AI 推荐';
    var slide=copy&&copy.querySelector('.charge-hero-slide.active');
    if(slide&&!slide.querySelector('[data-charge-ai-start]'))slide.insertAdjacentHTML('beforeend','<button class="charge-ai-start-v2" type="button" data-charge-ai-start>开始练习</button>');
    document.querySelectorAll('.charge-section-head h2').forEach(function(h){if(h.textContent.trim()==='今日方案')h.textContent='定制方案组合'});
  }
  function startChargeRecommendationV2(){
    if(typeof ensureTideSoundState==='function')ensureTideSoundState();
    if(typeof S!=='undefined'){
      S.chargeCategoryV7='ai';
      S.tideSoundMuted=false;
      try{localStorage.setItem('vivi:tideSoundMuted','0')}catch(_){}
    }
    if(typeof syncTideSoundButtons==='function')syncTideSoundButtons();
    if(typeof renderChargeContentIntoV7==='function')renderChargeContentIntoV7();
    ensureChargeRecommendationV2();
    var play=document.querySelector('[data-charge-play]');
    if(play)play.classList.add('is-playing');
    var start=document.querySelector('[data-charge-start-v1]');
    if(start)start.textContent='进行中';
    var status=document.querySelector('[data-charge-feedback-status]');
    if(status)status.textContent='已开始 12 分钟睡眠修复，白噪音占位播放中。';
    if(typeof playVoiceTone==='function')playVoiceTone(1400);
    if(typeof setCloudReaction==='function')setCloudReaction('speak',{force:true,returnIdle:true,hold:1400});
    if(typeof showVitalsStarNoticeV6==='function')showVitalsStarNoticeV6('已开始睡眠修复白噪音');
  }
  var prevEnsureTodayReportThreeTabV2=typeof ensureTodayEnergyReportEntryV1==='function'?ensureTodayEnergyReportEntryV1:null;
  if(prevEnsureTodayReportThreeTabV2&&!prevEnsureTodayReportThreeTabV2.__threeTabV2){
    ensureTodayEnergyReportEntryV1=function(){
      prevEnsureTodayReportThreeTabV2();
      ensureTodayThreeTabV2();
    };
    ensureTodayEnergyReportEntryV1.__threeTabV2=true;
  }
  openTodayEnergyReportV1=function(){openTodayBodyReportV2()};
  openHealthOverviewFromReportV1=function(){closeTodayEnergyReportV1();if(typeof switchTab==='function')switchTab('health');setTimeout(function(){if(typeof ensureHealthAiTranslatorV1==='function')ensureHealthAiTranslatorV1('energy');ensureHealthEvidenceFooterV1();},0)};
  openHealthDataDetailV1=function(key){closeTodayEnergyReportV1();openHealthOverviewFromReportV1()};
  openChargeFromReportV1=function(){
    closeTodayEnergyReportV1();
    if(typeof switchTab==='function')switchTab('vitals');
    setTimeout(function(){
      if(typeof renderVitalsStarOverviewV6==='function')renderVitalsStarOverviewV6();
      ensureChargeRecommendationV2();
      startChargeRecommendationV2();
    },0);
  };
  if(typeof renderVitalsStarOverviewV6==='function'&&!renderVitalsStarOverviewV6.__threeTabV2){
    var prevRenderVitalsStarThreeTabV2=renderVitalsStarOverviewV6;
    renderVitalsStarOverviewV6=function(){
      var result=prevRenderVitalsStarThreeTabV2.apply(this,arguments);
      if(window.__vitoraEnsurePillowTalkExploreV1){window.__vitoraEnsurePillowTalkExploreV1();return result}
      return result;
    };
    renderVitalsStarOverviewV6.__threeTabV2=true;
  }
  if(typeof renderChargeContentIntoV7==='function'&&!renderChargeContentIntoV7.__threeTabV2){
    var prevRenderChargeContentThreeTabV2=renderChargeContentIntoV7;
    renderChargeContentIntoV7=function(){
      var result=prevRenderChargeContentThreeTabV2.apply(this,arguments);
      if(window.__vitoraEnsurePillowTalkExploreV1)window.__vitoraEnsurePillowTalkExploreV1();
      return result;
    };
    renderChargeContentIntoV7.__threeTabV2=true;
  }
  if(typeof renderHealthDetailPage==='function'&&!renderHealthDetailPage.__threeTabV2){
    var prevRenderHealthDetailThreeTabV2=renderHealthDetailPage;
    renderHealthDetailPage=function(key){
      var result=prevRenderHealthDetailThreeTabV2.apply(this,arguments);
      if(typeof S!=='undefined'&&S.healthDailyReportOpenV2)injectHealthDailyReportV2();
      return result;
    };
    renderHealthDetailPage.__threeTabV2=true;
  }
  if(typeof switchTab==='function'&&!switchTab.__threeTabV2){
    var prevSwitchTabThreeTabV2=switchTab;
    switchTab=function(tab){
      var result=prevSwitchTabThreeTabV2.apply(this,arguments);
      if(tab==='today')setTimeout(ensureTodayThreeTabV2,0);
      if(tab==='health')setTimeout(ensureHealthSummaryGridV2,0);
      if(tab==='vitals')setTimeout(ensureChargeRecommendationV2,0);
      return result;
    };
    switchTab.__threeTabV2=true;
  }
  if(!document.documentElement.dataset.threeTabIaFixBoundV2){
    document.documentElement.dataset.threeTabIaFixBoundV2='1';
    document.addEventListener('click',function(e){
      if(e.target.closest('[data-today-cycle-settings]')){
        e.preventDefault();e.stopPropagation();if(e.stopImmediatePropagation)e.stopImmediatePropagation();openTodayCycleSettingsV2();return;
      }
      if(e.target.closest('[data-cycle-settings-close]')||e.target.id==='todayCycleSettingsLayerV2'){
        e.preventDefault();e.stopPropagation();if(e.stopImmediatePropagation)e.stopImmediatePropagation();closeTodayCycleSettingsV2();return;
      }
      if(e.target.closest('[data-cycle-settings-save]')){
        e.preventDefault();e.stopPropagation();if(e.stopImmediatePropagation)e.stopImmediatePropagation();saveTodayCycleSettingsV2();return;
      }
      var moduleHealth=e.target.closest('[data-open-health-module-v1]');
      if(moduleHealth){
        e.preventDefault();e.stopPropagation();if(e.stopImmediatePropagation)e.stopImmediatePropagation();
        if(typeof openHealthModuleEntryV1==='function')openHealthModuleEntryV1(moduleHealth);
        else if(typeof openVitoraNativeHealthDetail==='function'){openVitoraNativeHealthDetail(resolveHealthModulePayloadV1(moduleHealth).key,{origin:resolveHealthModulePayloadV1(moduleHealth).source,daily:resolveHealthModulePayloadV1(moduleHealth).daily});}
        return;
      }
      var summary=e.target.closest('[data-health-summary-detail]');
      if(summary){
        e.preventDefault();e.stopPropagation();if(e.stopImmediatePropagation)e.stopImmediatePropagation();openHealthDetailFromThreeTabV2(summary.getAttribute('data-health-summary-detail')||'weekly',false);return;
      }
      var aiStart=e.target.closest('[data-charge-ai-start]');
      var hero=e.target.closest('.charge-hero-slide.active');
      if(aiStart||hero){
        if(e.target.closest('[data-charge-hero-dot]'))return;
        e.preventDefault();e.stopPropagation();if(e.stopImmediatePropagation)e.stopImmediatePropagation();startChargeRecommendationV2();return;
      }
    },true);
  }
  ensureTodayThreeTabV2();
  ensureHealthSummaryGridV2();
  ensureChargeRecommendationV2();
`;

function applyThreeTabIaFix(html) {
  if (!html.includes("VIVI Three Tab IA Fix 20260622")) {
    if (html.includes("</head>")) {
      html = html.replace("</head>", `<style>\n${threeTabIaFixCss}\n</style>\n</head>`);
    } else {
      html = html.replace("</style>", `${threeTabIaFixCss}\n</style>`);
    }
  }

  if (!html.includes("threeTabIaFixBoundV2")) {
    html = html.replace(
      "  today.addEventListener('scroll',function(){",
      `${threeTabIaFixScript}\n  today.addEventListener('scroll',function(){`
    );
  }

  return html;
}

