function applyVitoraBodyDetailActionFix(html) {
  if (!html.includes("VIVI Body Detail Action Fix v4")) {
    if (html.includes("</head>")) {
      html = html.replace("</head>", `<style>\n${vitoraBodyDetailActionFixCss}\n</style>\n</head>`);
    } else {
      html = html.replace("</style>", `${vitoraBodyDetailActionFixCss}\n</style>`);
    }
  }

  if (!html.includes("vitoraBodyFixV4")) {
    html = html.replace(
      "  today.addEventListener('scroll',function(){",
      `${vitoraBodyDetailActionFixScript}\n  today.addEventListener('scroll',function(){`
    );
  }

  return html;
}

