function applyHealthSummaryDetailV10(html){
  if(!html.includes("VIVI Health Summary Detail V10")){
    if(html.includes("</head>"))html=html.replace("</head>", `<style>\n${healthSummaryDetailV10Css}\n</style>\n</head>`);
    else html=html.replace("</style>", `${healthSummaryDetailV10Css}\n</style>`);
  }
  if(!html.includes("__healthSummaryDetailV10")){
    html=html.replace("</body>", `<script>\n${healthSummaryDetailV10Script}\n</script>\n</body>`);
  }
  return html;
}

