    function set(az,copy){store.sunAzimuthV1=az;store.sunCopyV1=copy;ftRenderFixedTodayV1('morning')}
    if(route){var copy={outdoor:'优先找开阔处的直射或散射日光，先走 8 分钟。',window:'如果不方便出门，面向太阳方向选择窗边光照。',walk:'保持低强度轻走，不需要把它变成训练。'}[route]||'选择最容易执行的日光路线。';set(store.sunAzimuthV1||126,copy);return}
    if(navigator.geolocation){
      navigator.geolocation.getCurrentPosition(function(pos){var az=ssCalcSunV1(pos.coords.latitude,pos.coords.longitude,new Date());set(az,'已根据当前位置估算太阳方位。向箭头方向找开阔日光，避免强刺激训练。')},function(){set(126,'定位不可用，使用默认东南方向。向窗边或户外开阔处找柔和日光。')},{timeout:2800,maximumAge:600000});
    }else set(126,'当前 WebView 不支持定位，使用默认东南方向找日光。');
