  function ssChargeSessionForTitleV1(title){
    title=String(title||'').toLowerCase();
    if(title.indexOf('专注')>=0||title.indexOf('棕噪')>=0)return 'focus-25';
    if(title.indexOf('solfeggio')>=0||title.indexOf('频率')>=0||title.indexOf('黄体')>=0)return 'cycle-solfeggio';
    if(title.indexOf('3d')>=0||title.indexOf('音效')>=0||title.indexOf('组合')>=0||title.indexOf('节律')>=0)return 'today-journey';
    if(title.indexOf('睡')>=0||title.indexOf('白噪')>=0||title.indexOf('身体扫描')>=0)return 'sleep-white';
    if(title.indexOf('压力')>=0||title.indexOf('呼吸')>=0||title.indexOf('冥想')>=0)return 'stress-breath';
    if(title.indexOf('晨')>=0||title.indexOf('日光')>=0)return 'morning-sun';
    return 'today-journey';
  }
