  SoundscapeEngineV1=(function(){
    var ctx=null,master=null,nodes=[],panners=[],timer=null,panTimer=null,chimeTimer=null;
    var state={playing:false,sessionId:null,remaining:0,duration:0,noiseType:'pink',frequency:528,mode:'noise',pan:0,completed:false,startedAt:0};
    function ensureCtx(){
      ctx=ctx||new (window.AudioContext||window.webkitAudioContext)();
      if(!master){master=ctx.createGain();master.gain.value=.22;master.connect(ctx.destination)}
      return ctx;
    }
    function resumeCtx(){
      var c=ensureCtx();
      try{if(c.resume)c.resume()}catch(_){}
      return c;
    }
    function keep(n){nodes.push(n);return n}
    function stopNode(n){try{if(n.stop)n.stop()}catch(_){}try{if(n.disconnect)n.disconnect()}catch(_){}}
    function makeNoiseBuffer(type){
      var c=ensureCtx();var len=c.sampleRate*2;var buffer=c.createBuffer(1,len,c.sampleRate);var out=buffer.getChannelData(0);
      var b0=0,b1=0,b2=0,b3=0,b4=0,b5=0,b6=0,last=0;
      for(var i=0;i<len;i++){
        var white=Math.random()*2-1;
        if(type==='pink'||type==='rain'){
          b0=.99886*b0+white*.0555179;b1=.99332*b1+white*.0750759;b2=.969*b2+white*.153852;b3=.8665*b3+white*.3104856;b4=.55*b4+white*.5329522;b5=-.7616*b5-white*.016898;
          out[i]=(b0+b1+b2+b3+b4+b5+b6+white*.5362)*.075;b6=white*.115926;
        }else if(type==='brown'||type==='ocean'){
          last=(last+.018*white)/1.018;out[i]=last*2.6;
        }else out[i]=white*.18;
      }
      return buffer;
    }
    function connectPan(node,basePan){
      var target=node;
      if(ctx.createStereoPanner){
        var p=keep(ctx.createStereoPanner());p.pan.value=basePan||0;target.connect(p);target=p;panners.push(p);
      }
      target.connect(master);
      return target;
    }
    function addNoise(type,gainValue,filterFreq,pan){
      var source=keep(ctx.createBufferSource());source.buffer=makeNoiseBuffer(type);source.loop=true;
      var filter=keep(ctx.createBiquadFilter());filter.type=(type==='brown'||type==='ocean')?'lowpass':'bandpass';filter.frequency.value=filterFreq||((type==='white')?1600:680);filter.Q.value=(type==='white')?.45:.62;
      var gain=keep(ctx.createGain());gain.gain.value=gainValue||.055;
      source.connect(filter);filter.connect(gain);connectPan(gain,pan||0);source.start();
    }
    function addOsc(freq,type,gainValue,pan,detune){
      var osc=keep(ctx.createOscillator());var gain=keep(ctx.createGain());osc.type=type||'sine';osc.frequency.value=freq;osc.detune.value=detune||0;gain.gain.value=0;
      osc.connect(gain);connectPan(gain,pan||0);osc.start();
      gain.gain.setTargetAtTime(gainValue||.018,ctx.currentTime+.05,.8);
      return {osc:osc,gain:gain};
    }
    function addToneEnvelope(freq,type,peak,dur,pan,delay){
      var now=ctx.currentTime+(delay||0);var osc=keep(ctx.createOscillator());var gain=keep(ctx.createGain());
      osc.type=type||'sine';osc.frequency.setValueAtTime(freq,now);gain.gain.setValueAtTime(.0001,now);
      gain.gain.exponentialRampToValueAtTime(Math.max(.002,peak||.018),now+.045);
      gain.gain.exponentialRampToValueAtTime(.0001,now+Math.max(.22,dur||.9));
      osc.connect(gain);connectPan(gain,pan||0);osc.start(now);osc.stop(now+Math.max(.26,dur||.9)+.05);
    }
    function addStartCue(root,mode){
      var level=mode==='sleepDrift'?.010:.020;
      addToneEnvelope(root*1.5,'sine',level,.75,-.18,0);
      addToneEnvelope(root*2,'triangle',level*.72,.92,.18,.08);
      if(mode==='focusBox'||mode==='emotionBox'||mode==='journey3d')addToneEnvelope(root*2.5,'sine',level*.56,1.05,.42,.16);
    }
    function unlock(){
      resumeCtx();
      try{
        var now=ctx.currentTime;var osc=keep(ctx.createOscillator());var gain=keep(ctx.createGain());
        osc.type='sine';osc.frequency.setValueAtTime(392,now);gain.gain.setValueAtTime(.0001,now);
        gain.gain.exponentialRampToValueAtTime(.010,now+.018);
        gain.gain.exponentialRampToValueAtTime(.0001,now+.16);
        osc.connect(gain);connectPan(gain,0);osc.start(now);osc.stop(now+.18);
      }catch(_){}
      return ctx&&ctx.state;
    }
    function addLfo(target,rate,depth){
      var lfo=keep(ctx.createOscillator());var g=keep(ctx.createGain());lfo.type='sine';lfo.frequency.value=rate;g.gain.value=depth;lfo.connect(g);g.connect(target);lfo.start();
    }
    function addPad(root,mode){
      var chord={focusBox:[1,1.26,1.5],emotionBox:[1,1.2,1.5],journey3d:[1,1.25,1.68],sleepDrift:[1,.75,1.5],solfeggio:[1,2],morning:[1,1.33,1.5],breath:[1,1.25]}[mode]||[1,1.25,1.5];
      chord.forEach(function(r,i){var voice=addOsc(root*r,(i%2?'triangle':'sine'),mode==='sleepDrift'?.018:.026,(i-1)*.22,i*3);addLfo(voice.gain.gain,.045+i*.012,.004)});
    }
    function scheduleChimes(root,mode){
      if(mode==='sleepDrift')return;
      chimeTimer=setInterval(function(){
        if(!state.playing||!ctx)return;
        var f=root*[2,2.5,3,3.75][Math.floor(Math.random()*4)];
        var pan=(Math.random()*2-1)*.78;
        var bell=addOsc(f,'sine',.001,pan,0);
        bell.gain.gain.cancelScheduledValues(ctx.currentTime);
        bell.gain.gain.setValueAtTime(.0001,ctx.currentTime);
        bell.gain.gain.exponentialRampToValueAtTime(mode==='focusBox'?.035:.024,ctx.currentTime+.04);
        bell.gain.gain.exponentialRampToValueAtTime(.0001,ctx.currentTime+1.2);
        setTimeout(function(){stopNode(bell.osc);stopNode(bell.gain)},1600);
      },mode==='focusBox'?4200:5600);
    }
    function stop(){
      clearInterval(timer);clearInterval(panTimer);clearInterval(chimeTimer);timer=null;panTimer=null;chimeTimer=null;
      nodes.forEach(stopNode);nodes=[];panners=[];
      state.playing=false;
    }
    function rootFor(session){
      if(session.frequency)return Math.max(96,Math.min(528,Number(session.frequency)/2));
      return ({focusBox:174,emotionBox:196,journey3d:164,sleepDrift:110,solfeggio:132,morning:220,breath:146})[session.mode]||164;
    }
    function profileFor(session){
      var key=ssOptionV1(session.id+':mix','balanced');
      var map={
        easy:{key:'easy',label:'Easy',master:.16,noise:.72,bright:.82,panMs:1680,pad:.90,chime:.70},
        fluid:{key:'fluid',label:'Fluid',master:.19,noise:.86,bright:1.05,panMs:1180,pad:1.10,chime:1.00},
        balanced:{key:'balanced',label:'Balanced',master:.18,noise:.80,bright:.96,panMs:1320,pad:1.00,chime:.86},
        structured:{key:'structured',label:'Structured',master:.17,noise:.68,bright:1.22,panMs:1500,pad:.84,chime:1.18},
        intense:{key:'intense',label:'Intense',master:.22,noise:1.02,bright:1.35,panMs:900,pad:1.22,chime:1.32}
      };
      return map[key]||map.balanced;
    }
    function start(session,opts){
      session=ssSessionV1(session&&session.id?session.id:session);opts=opts||{};stop();resumeCtx();
      var profile=profileFor(session);
      if(master&&master.gain){
        try{master.gain.cancelScheduledValues(ctx.currentTime);master.gain.setValueAtTime(Math.max(.001,master.gain.value||.001),ctx.currentTime);master.gain.linearRampToValueAtTime(Math.max(.18,profile.master),ctx.currentTime+.10)}catch(_){master.gain.value=Math.max(.18,profile.master)}
      }
      var runDuration=Math.max(60,Number(opts.duration||ssOptionV1(session.id+':duration',session.duration)||session.duration)||session.duration);
      state={playing:true,sessionId:session.id,remaining:runDuration,duration:runDuration,noiseType:opts.noiseType||session.noiseType||'pink',frequency:Number(opts.frequency||session.frequency||528),mode:session.mode,pan:0,completed:false,startedAt:Date.now(),scene:ssOptionV1(session.id+':scene',session.voice||'Deep Work'),mix:profile.key};
      var root=rootFor(session);
      var baseFilter=state.noiseType==='white'?1900:state.noiseType==='brown'?360:760;
      var noiseGain=((session.mode==='focusBox'||session.mode==='emotionBox'||session.mode==='journey3d')?.052:.064)*profile.noise;
      addNoise(state.noiseType,noiseGain,baseFilter*profile.bright,-.18);
      if(session.mode==='sleepDrift'||session.mode==='morning')addNoise(state.noiseType==='brown'?'ocean':'rain',.020*profile.noise,(session.mode==='morning'?1400:420)*profile.bright,.22);
      addPad((session.mode==='solfeggio'?state.frequency:root)*profile.pad,session.mode);
      addStartCue(root,session.mode);
      if(session.mode==='solfeggio')addOsc(state.frequency,'sine',.020*profile.pad,0,0);
      if(session.mode==='breath'){var pulse=addOsc(root*.5,'sine',.014,0,0);addLfo(pulse.gain.gain,.08,.010)}
      resumeCtx();
      if(session.mode==='journey3d'||session.mode==='focusBox'||session.mode==='emotionBox'){
        panTimer=setInterval(function(){state.pan=Math.sin(Date.now()/profile.panMs);panners.forEach(function(p,i){try{p.pan.setTargetAtTime(Math.sin(Date.now()/(profile.panMs*.82+i*130)+i)*.82,ctx.currentTime,.16)}catch(_){}});ssSyncSoundscapeUiV1()},180);
      }
      scheduleChimes(root,session.mode);
      timer=setInterval(function(){if(!state.playing)return;state.remaining-=1;if(state.remaining<=0)complete();else ssSyncSoundscapeUiV1()},1000);
      ssSyncSoundscapeUiV1();
      return Object.assign({},state);
    }
    function pause(){if(ctx&&state.sessionId){try{if(ctx.suspend)ctx.suspend()}catch(_){}state.playing=false;ssSyncSoundscapeUiV1()}}
    function resume(){if(ctx&&state.sessionId){resumeCtx();state.playing=true;ssSyncSoundscapeUiV1();setTimeout(function(){try{resumeCtx();ssSyncSoundscapeUiV1()}catch(_){}},80)}}
    function complete(){
      var done=Object.assign({},state,{playing:false,completed:true,at:Date.now()});
      stop();state=done;
      try{localStorage.setItem('vivi:soundscape:lastComplete',JSON.stringify(done));var list=JSON.parse(localStorage.getItem('vivi:soundscape:history')||'[]');list.unshift(done);localStorage.setItem('vivi:soundscape:history',JSON.stringify(list.slice(0,20)))}catch(_){}
      ssSyncSoundscapeUiV1();
      if(typeof showPracticeFeedbackPopupButtonAuditV1==='function')showPracticeFeedbackPopupButtonAuditV1(done.sessionId||'soundscape');
    }
    return {start:start,stop:stop,pause:pause,resume:resume,complete:complete,unlock:unlock,state:function(){return Object.assign({},state)},context:function(){return ctx}};
  })();
  window.SoundscapeEngineV1=SoundscapeEngineV1;
  function ssRenderBarsV2(){return '<div class="soundscape-bars-v2" aria-hidden="true"><i style="height:12px"></i><i style="height:28px"></i><i style="height:18px"></i><i style="height:32px"></i><i style="height:16px"></i></div>'}
  function ssSessionDurationV2(s){
    var raw=Number(ssOptionV1(s.id+':duration',s.duration||1080));
    if(!raw||raw<60)raw=s.duration||1080;
    return Math.max(300,Math.min(5400,Math.round(raw/60)*60));
  }
  function ssSessionSceneTagsV1(s){
    var tags=[];
    if(s.category==='sleep'||s.mode==='sleepDrift')tags=tags.concat(['睡前','低刺激','助眠']);
    else if(s.mode==='morning')tags=tags.concat(['晨间','日光','轻启动']);
    else if(s.mode==='focusBox')tags=tags.concat(['专注','低干扰','单任务']);
    else if(s.mode==='emotionBox'||s.mode==='breath')tags=tags.concat(['冥想','呼吸','情绪降噪']);
    else if(s.mode==='journey3d')tags=tags.concat(['3D 声场','沉浸','空间感']);
    else if(s.mode==='solfeggio')tags=tags.concat(['频率','恢复','安定']);
    if(s.card==='cycle'||s.category==='cycle')tags.unshift('周期');
    return Array.from(new Set(tags)).slice(0,4);
  }
  function ssSessionStyleTagsV1(s){
    var tags=[];
    if(s.mode==='sleepDrift')tags=['山水','雾感','睡眠故事'];
    else if(s.mode==='morning')tags=['自然','晨光','窗边'];
    else if(s.mode==='focusBox')tags=['极简','棕噪','工作台'];
    else if(s.mode==='emotionBox')tags=['柔和','水彩','情绪盒'];
    else if(s.mode==='journey3d')tags=['空间','漂浮','慢移动'];
    else if(s.mode==='solfeggio')tags=['频率','低刺激','恢复'];
    else if(s.mode==='breath')tags=['呼吸','安静','身体感'];
    return tags;
  }
