  ssChargeSessionForTitleV1=function(title){
    var raw=String(title||'');if(ssSessionV1(raw)&&ssSessionV1(raw).id===raw)return raw;
    var norm=function(v){return String(v||'').toLowerCase().replace(/\s+/g,'')};
    var rawNorm=norm(raw);
    var chargeSearchItems=(typeof ssChargeNightItemsV9==='function'?ssChargeNightItemsV9():[]).concat(ssThemeLibraryItemsV1());
    var matched=chargeSearchItems.find(function(item){
      return norm(item.session)===rawNorm||norm(item.id)===rawNorm||norm(item.title)===rawNorm||rawNorm.indexOf(norm(item.title))>=0;
    });
    if(matched&&ssSessionV1(matched.session)&&ssSessionV1(matched.session).id===matched.session)return matched.session;
    var lower=raw.toLowerCase();
    if(lower.indexOf('solfeggio')>=0||raw.indexOf('频率')>=0)return 'solfeggio-528';
    if(raw.indexOf('情绪')>=0||lower.indexOf('emotion')>=0||raw.indexOf('盒')>=0)return 'emotion-3d-reset';
    if(raw.indexOf('3d')>=0||raw.indexOf('环绕')>=0||raw.indexOf('音效')>=0)return 'journey-orbit-8';
    if(raw.indexOf('专注')>=0||lower.indexOf('focus')>=0)return 'focus-afternoon-25';
    if(raw.indexOf('睡')>=0||raw.indexOf('助眠')>=0)return 'sleep-dream-brown-18';
    if(raw.indexOf('晨')>=0||raw.indexOf('太阳')>=0)return 'morning-sun-map';
    if(raw.indexOf('周期')>=0||raw.indexOf('黄体')>=0)return 'cycle-luteal-soft-10';
    return 'today-journey';
  };
