    var focusScore=pdClampV1(88-(f.focus.appSwitchesPerHour*2.2)-(f.focus.notificationCount*.22)-(f.focus.shortSessionRatio*18)+((sleepScore-70)*.18),30,96);
    var stressScore=pdClampV1(86-(f.stress.sleepDebtMinutes/18)-(f.stress.pickups*.22)-(f.stress.notificationCount*.15)-(f.sleep.awakenings*2.8),25,96);
