        focus:{score:focusScore,status:pdStatusV1(focusScore),confidence:.69,source:pdSourceForV1('focus',f.sources),drivers_good:focusScore>=70?['任务窗口可用']:['短任务更合适'],drivers_bad:['切换 '+f.focus.appSwitchesPerHour+'/h','通知 '+f.focus.notificationCount+' 条']},
