    if(state.states.stress.score<60)out.push({id:'breathing_box_4m',type:'active',surface:'deep_link',module:'抗压呼吸',title:'开始 4 分钟箱式呼吸',reason:'抗压韧性偏低，短呼吸比继续硬推更合适。',target:'emotion-breath-3',session:'emotion-breath-3',push:'先做 4 分钟箱式呼吸，把身体从紧绷切回来。'});
