    if(state.states.focus.score<70&&hour>=9&&hour<18)out.push({id:'focus_25m',type:'active',surface:'deep_link',module:'专注 25 分钟',title:'开始 25 分钟专注',reason:'切换频率偏高，单任务比继续多线程更稳。',target:'focus-afternoon-25',session:'focus-afternoon-25',push:'只推进一个清晰任务，结束后离屏 3 分钟。'});
    if(state.states.morning.score<76&&hour<11)out.push({id:'morning_sun_8m',type:'active',surface:'deep_link',module:'日光地图',title:'开始找太阳',reason:'晨间启动偏慢，短日光暴露比咖啡硬拉更合适。',target:'morning-sun-map',session:'morning-sun-map',push:'向太阳方向找开阔日光或窗边光 8 分钟。'});
    if(state.states.cycle.phase==='luteal'||state.states.cycle.phase==='menstrual')out.push({id:'cycle_low_stim',type:'passive',surface:'push',module:'周期低刺激',title:'保留低刺激恢复窗口',reason:state.states.cycle.phase_label+'阈值下调，适合温和节律。',target:'cycle-luteal-soft-10',session:'cycle-luteal-soft-10',push:'下午保留一个低刺激恢复窗口，减少硬推。'});
