  function ssRenderCycleStretchRingV8(model){
    var phases=[
      {key:'经期',start:-118,end:-76,color:'#ff92ad'},
      {key:'卵泡期',start:-160,end:-122,color:'#7fe9d7'},
      {key:'排卵期',start:72,end:112,color:'#a99cff'},
      {key:'黄体期',start:-72,end:66,color:'#ffd348'}
    ];
    var ticks=[];
    phases.forEach(function(p){
      var count=p.key===model.phase?18:8;
      for(var i=0;i<count;i++){
        var t=count===1?0:i/(count-1);
        var angle=p.start+(p.end-p.start)*t;
        var active=p.key===model.phase;
        ticks.push('<i class="'+(active?'active':'muted')+'" style="--a:'+angle+'deg;--len:'+(active?48:32)+'px;--c:'+p.color+'"></i>');
      }
    });
    return '<div class="v8-cycle-stretch" aria-label="周期阶段轴"><div class="v8-cycle-ticks">'+ticks.join('')+'</div><span class="v8-cycle-phase-label label-period">经期</span><span class="v8-cycle-phase-label label-follicular">卵泡期</span><span class="v8-cycle-phase-label label-ovulation">排卵期</span><span class="v8-cycle-phase-label label-luteal active">黄体期</span><div class="v8-cycle-center"><strong>'+ssDotNumberV7('D'+model.day,78)+'</strong><span>本月第 '+model.day+' 天</span></div></div>';
  }
