    var rec=ssFocusRecommendationV7(score);var durations=[1500,2700,3000];var stored=Number(ssOptionV1(s.id+':duration',''));if(durations.indexOf(stored)<0){stored=rec.seconds;ssSetOptionV1(s.id+':duration',String(stored))}
    s.duration=stored;var duration=ssSessionDurationV2(s);var focusMin=Math.round(duration/60);var focusDisplay=active?ssFormatTimeV1(remaining||duration):focusMin;var bars=[24,30,38,48,58,68,78,88,72,62,52,44,36,30,24];
