    if(!layer){layer=document.createElement('section');layer.id='chargePlanLayerV1';layer.className='charge-plan-layer-v1';document.body.appendChild(layer)}
    var titleText=item.title||s.title;var subtitle=item.subtitle||s.subtitle;var tags=(item.tags||ssSessionSceneTagsV1(s)).slice(0,4);
    layer.innerHTML='<article class="soundscape-player-sheet-v1 soundscape-player-v5 charge-player-sheet-v2" role="dialog" aria-modal="true" aria-label="声场详情"><header class="vitora-sheet-head-v1"><div><div class="charge-player-tags-v2">'+tags.map(function(t){return '<span>'+ssEscV1(t)+'</span>'}).join('')+'</div><h2>'+ssEscV1(titleText)+'</h2><p>'+ssEscV1(subtitle)+'</p></div><button class="vitora-sheet-close-v1" type="button" data-charge-plan-close aria-label="关闭">×</button></header><div class="charge-player-hero-v2">'+ssThemeCoverV8(item,'wide')+'<div class="charge-player-hero-copy-v2"><em>'+ssEscV1((item.toolType||s.mode||'声音场景'))+'</em><strong>'+ssEscV1(titleText)+'</strong><span>'+ssEscV1(item.reason||s.reason)+'</span></div></div><button class="charge-player-start-v2" type="button" data-start-idle="开始练习第 1 章" data-charge-player-start-v2="'+ssEscV1(id)+'">▶ 开始练习第 1 章</button><div class="charge-player-info-grid-v2"><section class="charge-player-info-card-v2"><b>为什么推荐</b><span>'+ssEscV1(item.reason||s.reason)+'</span></section><section class="charge-player-info-card-v2"><b>推荐依据</b><span>'+ssEscV1(subtitle)+' · '+ssEscV1((item.style||[]).join(' / ')||s.mode)+' · 今日状态匹配</span></section></div>'+ssRenderChargeSourceBlockV2(item,s)+ssRenderChargeChapterListV2(item,s)+ssRenderChargeTipsV2(item)+ssRenderUsePanelV1(id)+'</article>';
    layer.classList.add('open');layer.setAttribute('aria-hidden','false');ssSyncSoundscapeUiV1();
