function applyLightStateTodaySkin(html) {
  if (!html.includes("VIVI Light State Glass UI 20260626")) {
    if (html.includes("</head>")) {
      html = html.replace("</head>", `<style>\n${lightStateTodayCss}\n</style>\n</head>`);
    } else {
      html = html.replace("</style>", `${lightStateTodayCss}\n</style>`);
    }
  }
  return html;
}

