const healthFrostedTabsV7Script = String.raw`
  function ensureHealthFrostedTabsV7(){
    document.querySelectorAll('.planet-stress .planet-label').forEach(function(n){n.textContent='抗压能力'});
    document.querySelectorAll('.planet-activity .planet-label').forEach(function(n){n.textContent='能量'});
    var primary=document.querySelector('.screen[data-screen="health"] .state-action.primary');
    if(primary)primary.textContent='更多';
    var tiles=document.querySelectorAll('.screen[data-screen="health"] .tile');
    if(tiles[0]){
      var k=tiles[0].querySelector('.tile-k'),v=tiles[0].querySelector('.tile-v'),s=tiles[0].querySelector('.tile-s');
      if(k)k.textContent='平均准备度';
      if(v)v.textContent='88';
      if(s)s.textContent='整体稳定';
	      tiles[0].setAttribute('data-health-summary-detail','weekly');
	      tiles[0].removeAttribute('data-health-detail');
	      tiles[0].removeAttribute('data-health-node');
	      tiles[0].removeAttribute('data-detail');
    }
    if(tiles[1]){
      var k2=tiles[1].querySelector('.tile-k'),v2=tiles[1].querySelector('.tile-v'),s2=tiles[1].querySelector('.tile-s');
      if(k2)k2.textContent='睡眠负债';
      if(v2)v2.textContent='+2';
      if(s2)s2.textContent='轻度';
	      tiles[1].setAttribute('data-health-summary-detail','sleepdebt');
	      tiles[1].removeAttribute('data-health-node');
	      tiles[1].removeAttribute('data-health-detail');
	      tiles[1].removeAttribute('data-detail');
    }
  }
  document.addEventListener('click',function(e){
    var node=e.target.closest('.phone[data-tab="health"] [data-health-node]');
    var state=(typeof S!=='undefined'&&S)||{};
    if(node&&!state.healthDetailOpen){
      var key=node.getAttribute('data-health-node');
      var detailMap={sleep:'sleep',stress:'stress',cycle:'cycle',activity:'activity',recovery:'readiness'};
      if(detailMap[key]&&(typeof openUnifiedVitalDetail==='function'||typeof openHealthDetail==='function'||typeof openVitalsDetailPageV2==='function')){
        e.preventDefault();
        e.stopPropagation();
        if(e.stopImmediatePropagation)e.stopImmediatePropagation();
        if(typeof openUnifiedVitalDetail==='function')openUnifiedVitalDetail(detailMap[key],'health');
        else if(typeof openHealthDetail==='function')openHealthDetail(detailMap[key]);
        else if(typeof openVitalsDetailPageV2==='function'){
          if(typeof switchTab==='function')switchTab('vitals');
          openVitalsDetailPageV2(detailMap[key]);
        }
        return;
      }
    }
  },true);
  ensureHealthFrostedTabsV7();
`;

