const healthPlanetV8Script = String.raw`
  function ensureHealthPlanetV8(){
    var stage=document.querySelector('.screen[data-screen="health"] .galaxy-stage');
    if(stage)stage.setAttribute('data-health-planet-v8','clean-asset');
    var routeHealthPlanet=function(key,e){
      var map={cycle:'cycle',sleep:'sleep',stress:'stress',activity:'activity'};
      var target=map[key];
      var state=(typeof S!=='undefined'&&S)||{};
      if(!target||state.healthDetailOpen)return;
      var now=Date.now();
      if(routeHealthPlanet.last&&now-routeHealthPlanet.last<360)return;
      routeHealthPlanet.last=now;
      if(e){
        e.preventDefault();
        e.stopPropagation();
        if(e.stopImmediatePropagation)e.stopImmediatePropagation();
      }
      if(typeof openUnifiedVitalDetail==='function')openUnifiedVitalDetail(target,'health');
      else if(typeof openHealthDetail==='function')openHealthDetail(target);
      else if(typeof openVitalsDetailPageV2==='function'){
        if(typeof switchTab==='function')switchTab('vitals');
        openVitalsDetailPageV2(target);
      }
      else if(typeof switchTab==='function'){
        switchTab('vitals');
        setTimeout(function(){
          var card=document.querySelector('[data-vital-open="'+target+'"]');
          if(card&&typeof card.click==='function')card.click();
        },80);
      }
    };
    document.querySelectorAll('.screen[data-screen="health"] .galaxy-planet').forEach(function(btn){
      var key=btn.getAttribute('data-health-node');
      btn.setAttribute('title',btn.getAttribute('aria-label')||'查看身体信号');
      btn.setAttribute('role','button');
      btn.removeAttribute('aria-pressed');
      if({cycle:1,sleep:1,stress:1,activity:1}[key]){
        btn.onclick=function(e){routeHealthPlanet(key,e)};
        btn.onpointerup=function(e){routeHealthPlanet(key,e)};
        btn.ontouchend=function(e){routeHealthPlanet(key,e)};
      }
    });
    if(document.documentElement.dataset.healthPlanetV8Hotspots==='1')return;
    document.documentElement.dataset.healthPlanetV8Hotspots='1';
    document.addEventListener('click',function(e){
      var phone=document.querySelector('.phone');
      var state=(typeof S!=='undefined'&&S)||{};
      if(!phone||phone.getAttribute('data-tab')!=='health'||state.healthDetailOpen||state.detail||state.plus)return;
      if(e.target.closest('.bottom,.health-state-panel,.cloud-mascot,.profile-sheet,.home-space-sheet,.vitals-detail-page'))return;
      var stage=document.querySelector('.screen[data-screen="health"] .galaxy-stage');
      if(!stage)return;
      var rect=stage.getBoundingClientRect();
      var x=e.clientX-rect.left;
      var y=e.clientY-rect.top;
      if(x<0||y<0||x>rect.width||y>rect.height)return;
      var boxes=[
        {key:'cycle',left:-8,top:78,right:146,bottom:204},
        {key:'sleep',left:66,top:104,right:232,bottom:238},
        {key:'stress',left:194,top:108,right:388,bottom:246},
        {key:'activity',left:rect.width-136,top:96,right:rect.width+8,bottom:228}
      ];
      var hit=boxes.find(function(box){return x>=box.left&&x<=box.right&&y>=box.top&&y<=box.bottom});
      if(!hit)return;
      e.preventDefault();
      e.stopPropagation();
      if(e.stopImmediatePropagation)e.stopImmediatePropagation();
      if(typeof openUnifiedVitalDetail==='function')openUnifiedVitalDetail(hit.key,'health');
      else if(typeof openHealthDetail==='function')openHealthDetail(hit.key);
    },true);
  }
`;

