async function exists(filePath) {
  try {
    await fs.access(filePath);
    return true;
  } catch {
    return false;
  }
}

async function copyFile(source, target) {
  if (!(await exists(source))) {
    throw new Error(`Missing required source asset: ${source}`);
  }

  await fs.mkdir(path.dirname(target), { recursive: true });
  await fs.copyFile(source, target);
}

async function copyDir(source, target) {
  if (!(await exists(source))) {
    throw new Error(`Missing required source directory: ${source}`);
  }

  await fs.rm(target, { force: true, recursive: true });
  await fs.mkdir(target, { recursive: true });

  const entries = await fs.readdir(source, { withFileTypes: true });
  for (const entry of entries) {
    const src = path.join(source, entry.name);
    const dst = path.join(target, entry.name);
    if (entry.isDirectory()) {
      await copyDir(src, dst);
    } else if (entry.isFile()) {
      await copyFile(src, dst);
    }
  }
}

function execFile(command, args) {
  return new Promise((resolve, reject) => {
    const child = spawn(command, args, { stdio: ["ignore", "pipe", "pipe"] });
    let stderr = "";
    child.stderr.on("data", (chunk) => {
      stderr += chunk.toString();
    });
    child.on("error", reject);
    child.on("close", (code) => {
      if (code === 0) resolve();
      else reject(new Error(`${command} exited with ${code}: ${stderr.trim()}`));
    });
  });
}

async function preprocessWeeklyThemePlanet(source, target) {
  await fs.mkdir(path.dirname(target), { recursive: true });
  const python = String.raw`
import sys
from collections import deque
from PIL import Image, ImageFilter

src, dst = sys.argv[1], sys.argv[2]
im = Image.open(src).convert("RGBA")
w, h = im.size
pix = im.load()

def is_edge_bg(x, y):
    r, g, b, a = pix[x, y]
    if a == 0:
        return True
    high_neutral = r > 220 and g > 220 and b > 220 and max(r, g, b) - min(r, g, b) < 24
    soft_neutral = r > 214 and g > 214 and b > 214 and abs(r - g) < 15 and abs(g - b) < 15
    return high_neutral or soft_neutral

seen = bytearray(w * h)
queue = deque()

def push(x, y):
    i = y * w + x
    if seen[i] or not is_edge_bg(x, y):
        return
    seen[i] = 1
    queue.append((x, y))

for x in range(w):
    push(x, 0)
    push(x, h - 1)
for y in range(h):
    push(0, y)
    push(w - 1, y)

while queue:
    x, y = queue.popleft()
    if x > 0:
        push(x - 1, y)
    if x < w - 1:
        push(x + 1, y)
    if y > 0:
        push(x, y - 1)
    if y < h - 1:
        push(x, y + 1)

alpha = Image.new("L", (w, h), 255)
ap = alpha.load()
for y in range(h):
    row = y * w
    for x in range(w):
        if seen[row + x]:
            ap[x, y] = 0

alpha = alpha.filter(ImageFilter.GaussianBlur(0.65))
im.putalpha(alpha)
im.save(dst, optimize=True)
`;

  try {
    await execFile("python3", ["-c", python, source, target]);
  } catch (error) {
    console.warn(`Weekly theme planet preprocessing failed, copied original: ${path.basename(source)}\n${error.message}`);
    await copyFile(source, target);
  }
}

async function copyWeeklyThemePlanets() {
  const targetRoot = path.join(webRoot, "assets", "weekly-theme-planets");
  await fs.mkdir(targetRoot, { recursive: true });
  const shouldPreprocess = process.env.VIVI_PREPROCESS_WEEKLY_PLANETS === "1";

  async function writePlaceholder(theme) {
    const target = path.join(targetRoot, `${theme}.png`);
    if (await exists(target)) return;
    await fs.writeFile(target, transparentPixelPng);
  }

  if (!(await exists(weeklyThemePlanetSource))) {
    console.warn(`Weekly theme planet source folder missing, skipped: ${weeklyThemePlanetSource}`);
    for (const theme of Object.keys(weeklyThemePlanetFiles)) {
      await writePlaceholder(theme);
    }
    return;
  }

  for (const [theme, fileName] of Object.entries(weeklyThemePlanetFiles)) {
    const source = path.join(weeklyThemePlanetSource, fileName);
    const target = path.join(targetRoot, `${theme}.png`);
    if (!(await exists(source))) {
      console.warn(`Weekly theme planet source image missing, skipped: ${source}`);
      await writePlaceholder(theme);
      continue;
    }
    if (shouldPreprocess) {
      await preprocessWeeklyThemePlanet(source, target);
    } else {
      await copyFile(source, target);
    }
  }
}

async function inlineWeeklyThemePlanets(html) {
  const targetRoot = path.join(webRoot, "assets", "weekly-theme-planets");
  for (const theme of Object.keys(weeklyThemePlanetFiles)) {
    const imagePath = path.join(targetRoot, `${theme}.png`);
    if (!(await exists(imagePath))) continue;
    const image = await fs.readFile(imagePath);
    const dataUri = `data:image/png;base64,${image.toString("base64")}`;
    html = html.replaceAll(
      `'./assets/weekly-theme-planets/${theme}.png'`,
      JSON.stringify(dataUri)
    );
  }
  return html;
}

async function inlineTideWallpaperVideos(html) {
  const fileNames = [
    "today-energy.mp4",
    "snow-lake.mp4",
    "sun-lake.mp4",
    "green-forest.mp4",
    "reeds-water.mp4",
    "mist-temple.mp4"
  ];

  const fallbackVideoPath = path.join(tideWallpaperSource, "today-energy.mp4");
  for (const fileName of fileNames) {
    let videoPath = path.join(tideWallpaperSource, fileName);
    if (!(await exists(videoPath))) {
      if (!(await exists(fallbackVideoPath))) {
        throw new Error(`Missing tide wallpaper video and fallback: ${videoPath}`);
      }
      console.warn(`Tide wallpaper video missing, using today-energy fallback: ${videoPath}`);
      videoPath = fallbackVideoPath;
    }

    const video = await fs.readFile(videoPath);
    const dataUri = `data:video/mp4;base64,${video.toString("base64")}`;
    html = html.replaceAll(
      `'./assets/tide-wallpapers/${fileName}'`,
      JSON.stringify(dataUri)
    );
  }

  return html;
}

